<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: 'auth' })
const { data: initialPage } = await useFetch('/api/organization/audit')
const events = ref<any[]>(initialPage.value?.events ?? []); const cursor = ref<string | null>(initialPage.value?.nextCursor ?? null); const loading = ref(false)
async function load() { loading.value = true; try { const page = await $fetch('/api/organization/audit', { query: cursor.value ? { cursor: cursor.value } : {} }); events.value.push(...page.events); cursor.value = page.nextCursor } finally { loading.value = false } }
</script>
<template><section class="max-w-5xl"><NuxtLink to="/admin/organization" class="text-sm underline">← 組織設定へ</NuxtLink><h1 class="mt-5 text-2xl font-bold">監査ログ</h1><div class="mt-6 divide-y border-y border-stone-200"><article v-for="event in events" :key="event.id" class="py-4"><div class="flex flex-wrap justify-between gap-2"><strong>{{ event.action }}</strong><time class="text-sm text-stone-500">{{ new Date(event.createdAt).toLocaleString('ja-JP') }}</time></div><p class="mt-1 text-sm">{{ event.actorUser?.displayName || event.actorUser?.email || 'SYSTEM' }} · {{ event.targetType }} / {{ event.targetId }}</p><details v-if="Object.keys(event.metadata ?? {}).length" class="mt-2"><summary class="w-fit cursor-pointer text-xs text-stone-600">操作の詳細</summary><pre class="mt-2 overflow-auto text-xs text-stone-500">{{ JSON.stringify(event.metadata, null, 2) }}</pre></details></article></div><button v-if="cursor" :disabled="loading" class="mt-4 rounded border px-4 py-2" @click="load">続きを読み込む</button></section></template>
